import { useState, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addUserMessage, addAssistantMessage, setError, selectActiveChat } from '../../store/slices/chatSlice';
import { selectModel } from '../../store/slices/uiSlice';
import { sendMessage as aiSend } from '../../utils/aiService';
import { useTheme } from '../../hooks/useTheme';
import { useSpeech } from '../../hooks/useSpeech';
import PlusMenu from './PlusMenu';
import ModelDropdown from './ModelDropdown';
import IconButton from '../ui/IconButton';

export default function ChatInput() {
  const dispatch    = useDispatch();
  const activeChat  = useSelector(selectActiveChat);
  const modelId     = useSelector(selectModel);
  const { chatHex, borderHex, inputHex, textHex, mutedHex } = useTheme();

  const [input,       setInput]       = useState('');
  const [attachments, setAttachments] = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [plusOpen,    setPlusOpen]    = useState(false);
  const textareaRef = useRef(null);

  const { listening, toggle: toggleMic } = useSpeech((text) =>
    setInput((prev) => prev + text)
  );

  const autoResize = () => {
    const ta = textareaRef.current;
    if (!ta) return;
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight, 180) + 'px';
  };

  const send = async () => {
    if (!input.trim() && attachments.length === 0) return;
    const content = input.trim();
    const atts    = [...attachments];

    setInput('');
    setAttachments([]);
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
    setLoading(true);
    setPlusOpen(false);

    dispatch(addUserMessage({ content, attachments: atts }));

    const history = [
      ...(activeChat?.messages ?? []),
      { role: 'user', content: content || '(file attached)' },
    ].map((m) => ({ role: m.role, content: m.content }));

    try {
      const reply = await aiSend(modelId, history);
      dispatch(addAssistantMessage(reply));
    } catch (err) {
      dispatch(addAssistantMessage(`⚠️ ${err.message}`));
      dispatch(setError(err.message));
    }
    setLoading(false);
  };

  const onKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
  };

  const onFile = (files) =>
    setAttachments((prev) => [...prev, ...files.map((f) => ({ name: f.name, type: f.type }))]);

  const onScreenshot = () =>
    setAttachments((prev) => [...prev, { name: 'screenshot.png', type: 'image/png' }]);

  const canSend = (input.trim() || attachments.length > 0) && !loading;

  return (
    <div style={{ padding: '12px 20px 16px', background: chatHex, borderTop: `1px solid ${borderHex}` }}>
      {/* Attachment chips */}
      {attachments.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
          {attachments.map((a, i) => (
            <div key={i} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, background: inputHex, borderRadius: 8, padding: '4px 10px', fontSize: 12.5, color: textHex }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              {a.name}
              <button style={{ background: 'none', border: 'none', cursor: 'pointer', color: mutedHex, padding: 0 }} onClick={() => setAttachments((p) => p.filter((_, j) => j !== i))}>×</button>
            </div>
          ))}
        </div>
      )}

      {/* Input box */}
      <div style={{ background: inputHex, border: `1.5px solid ${borderHex}`, borderRadius: 14, padding: '10px 10px 10px 14px', display: 'flex', flexDirection: 'column', gap: 8 }}>
        <textarea
          ref={textareaRef}
          rows={1}
          value={input}
          onChange={(e) => { setInput(e.target.value); autoResize(); }}
          onKeyDown={onKey}
          placeholder="Message HelixtaAI..."
          style={{
            resize: 'none', outline: 'none', border: 'none', background: 'transparent',
            fontFamily: "'DM Sans', sans-serif", fontSize: 14.5, color: textHex,
            width: '100%', lineHeight: 1.6, maxHeight: 180,
          }}
        />

        {/* Toolbar — single line */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>

          {/* Plus button + menu */}
          <div style={{ position: 'relative' }}>
            <IconButton onClick={() => setPlusOpen((p) => !p)} title="Attachments" active={plusOpen}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2"><path d="M12 5v14M5 12h14"/></svg>
            </IconButton>
            <PlusMenu open={plusOpen} onClose={() => setPlusOpen(false)} onFile={onFile} onScreenshot={onScreenshot}/>
          </div>

          {/* Mic */}
          <IconButton onClick={toggleMic} title={listening ? 'Stop' : 'Voice input'} danger={listening} style={{ animation: listening ? 'pulse2 1s infinite' : 'none' }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <rect x="9" y="2" width="6" height="12" rx="3"/>
              <path d="M5 10a7 7 0 0 0 14 0M12 19v3M9 22h6"/>
            </svg>
          </IconButton>

          <div style={{ flex: 1 }}/>

          {/* Model dropdown */}
          <ModelDropdown/>

          {/* Send */}
          <button onClick={send} disabled={!canSend} style={{
            width: 36, height: 36, borderRadius: 10, border: 'none', flexShrink: 0,
            background: canSend ? 'linear-gradient(135deg,#6366f1,#8b5cf6)' : (inputHex),
            cursor: canSend ? 'pointer' : 'default',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            transition: 'background 0.2s',
          }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={canSend ? '#fff' : mutedHex} strokeWidth="2.2">
              <line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/>
            </svg>
          </button>
        </div>
      </div>
      <p style={{ fontSize: 11.5, color: mutedHex, textAlign: 'center', marginTop: 8 }}>HelixtaAI can make mistakes. Verify important information.</p>
    </div>
  );
}
